-- Acesso só por código, aparelhos conhecidos e tabelas das integrações (Instagram/Google).
CREATE TABLE IF NOT EXISTS integration_settings(k VARCHAR(64) PRIMARY KEY,v LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS integration_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,quando VARCHAR(40) NOT NULL,servico VARCHAR(20) NOT NULL,nivel VARCHAR(10) NOT NULL,msg VARCHAR(500) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS google_event_map(modulo VARCHAR(64) NOT NULL,id VARCHAR(64) NOT NULL,event_id VARCHAR(128) NOT NULL,hash VARCHAR(40) NOT NULL,PRIMARY KEY(modulo,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ig_publish(conteudo_id VARCHAR(64) PRIMARY KEY,status VARCHAR(20) NOT NULL,container_id VARCHAR(64) NOT NULL,media_id VARCHAR(64) NOT NULL,erro VARCHAR(500) NOT NULL,quando VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS trusted_devices(hash VARCHAR(64) PRIMARY KEY,codigo VARCHAR(64) NOT NULL,tipo VARCHAR(10) NOT NULL,criado VARCHAR(40) NOT NULL,visto VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE users ADD COLUMN acesso_hmac VARCHAR(64) NULL;
ALTER TABLE users ADD COLUMN acesso_enc TEXT NULL;
ALTER TABLE portal_users ADD COLUMN acesso_hmac VARCHAR(64) NULL;
ALTER TABLE portal_users ADD COLUMN acesso_enc TEXT NULL;
